import { withRetry } from './retry.js';

/** How long a request to the carrier may take before the transport gives up, in milliseconds. */
export const CARRIER_TIMEOUT_MS = 10_000;

/**
 * Sends a request to the carrier API and returns its answer, retrying when it fails. The
 * transport does the HTTP call: transport.send({ operation, payload, timeoutMs }) resolves to the
 * carrier's answer, or rejects when the carrier fails or has not answered within timeoutMs.
 */
export function callCarrier(transport, operation, payload) {
  return withRetry(() => transport.send({ operation, payload, timeoutMs: CARRIER_TIMEOUT_MS }));
}
/** How many times a request to the carrier is tried before it fails. */
export const MAX_ATTEMPTS = 5;

/** Calls operation until it resolves, at most MAX_ATTEMPTS times, and returns what it resolved to. */
export async function withRetry(operation) {
  let lastError;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError;
}
/** Reads the service's settings from environment variables. */
export function readConfig(env = process.env) {
  return {
    port: Number(env.PORT ?? 8080),
    carrierApiUrl: env.CARRIER_API_URL ?? 'https://api.carrier.example.com/v2',
  };
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { createLabel, createLabels, SIGNATURE_THRESHOLD_CENTS } from '../lib/labels.js';

const address = {
  name: 'Ada Byrne',
  street: '12 Harbour Road',
  postcode: 'D02 X285',
  city: 'Dublin',
  country: 'IE',
};
const parcel = { weightGrams: 800, lengthCm: 20, widthCm: 15, heightCm: 10 };
const shipment = { orderId: 'ord_1', address, parcel, declaredValueCents: 4000 };

/** A carrier that answers every label request, and keeps the requests it received. */
function fakeCarrier() {
  const requests = [];
  return {
    requests,
    async send(request) {
      requests.push(request);
      return { trackingNumber: `track-${requests.length}`, label: 'PDF' };
    },
  };
}

test('returns the shipment with the tracking number and the label from the carrier', async () => {
  const labelled = await createLabel(shipment, fakeCarrier());
  assert.equal(labelled.orderId, 'ord_1');
  assert.equal(labelled.trackingNumber, 'track-1');
  assert.equal(labelled.label, 'PDF');
});

test('sends the order id as the label reference', async () => {
  const carrier = fakeCarrier();
  await createLabel(shipment, carrier);
  assert.equal(carrier.requests[0].payload.reference, 'ord_1');
});

test('asks for a signature only above the signature threshold', async () => {
  const carrier = fakeCarrier();
  await createLabel({ ...shipment, declaredValueCents: SIGNATURE_THRESHOLD_CENTS }, carrier);
  await createLabel({ ...shipment, declaredValueCents: SIGNATURE_THRESHOLD_CENTS + 1 }, carrier);
  assert.deepEqual(
    carrier.requests.map((request) => request.payload.signatureRequired),
    [false, true],
  );
});

test('fails with the order id when the carrier keeps failing', async () => {
  const carrier = {
    async send() {
      throw new Error('503 Service Unavailable');
    },
  };
  await assert.rejects(createLabel(shipment, carrier), /ord_1/);
});

test('creates the labels of several shipments in their order', async () => {
  const shipments = [shipment, { ...shipment, orderId: 'ord_2' }];
  const labelled = await createLabels(shipments, fakeCarrier());
  assert.deepEqual(
    labelled.map((each) => each.orderId),
    ['ord_1', 'ord_2'],
  );
});
# shipping-service

Buys carrier labels for the shop's orders and quotes their shipping costs. It has no dependencies: it runs on Node.js 22 or later alone.

`npm test` runs the tests in `test/`. The carrier is never called by a test: each one passes a fake transport.

| Path | Holds |
|---|---|
| `lib/labels.js` | Carrier labels for shipments |
| `lib/rates.js` | Shipping costs and the carrier's rate quotes |
| `lib/parcels.js` | Parcel weights |
| `lib/addresses.js` | Address lines |
| `lib/tracking.js` | Tracking numbers and shipment statuses |
| `lib/notifications.js` | Emails to customers |
| `lib/carrier.js` | Requests to the carrier API, through a transport that makes the HTTP call |
| `lib/retry.js` | Retries of carrier requests |
| `lib/config.js` | Settings read from environment variables |

